"""End-to-end TECHNICAL FIXTURE through existing renderer + new intake, no human labels/model calls."""
from pathlib import Path
import importlib.util,json,subprocess
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'outputs/manual-audit-intake-2026-11-11'
spec=importlib.util.spec_from_file_location('intake',ROOT/'tools/receive-review-cards.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
demo=OUT/'TECHNICAL_FIXTURE';demo.mkdir();source=demo/'source';(source/'reviewer').mkdir(parents=True)
prototype=m.read(ROOT/'outputs/review-card-fragments-2026-11-11/demo-final/cards.json')['cards'][-1]
base={k:v for k,v in prototype.items() if k!='citation_readout'}
m.save(source/'reviewer/cards.json',{'phase':'POST-LABEL TECHNICAL_FIXTURE: fabricated invalid-reference example, no human review','cards':[base]})
(source/'reviewer/READ_FIRST.txt').write_text('TECHNICAL FIXTURE, not real pilot.',encoding='utf-8')
m.save(source/'PRIVATE_COORDINATOR.json',{'selection':[{'audit_id':base['audit_id'],'source_id':'TECHNICAL_FIXTURE','stratum':'fixture'}],'protocol_sha256':'fixture-not-real-sampling-protocol'})
m.save(source/'MANIFEST.json',{n:m.digest(source/n) for n in ['reviewer/cards.json','reviewer/READ_FIRST.txt','PRIVATE_COORDINATOR.json']})
rendered=demo/'rendered'
command=[str(ROOT/'work/lat-ai-runtime/node/node.exe'),str(ROOT/'tools/render-signal-review-cards.mjs'),'render',str(m.PRESENTATION),str(source),str(rendered)]
run=subprocess.run(command,capture_output=True,text=True,encoding='utf-8',creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
(demo/'renderer.log').write_text(run.stdout+run.stderr,encoding='utf-8');run.check_returncode()
reviewer='11111111-1111-4111-8111-111111111111';coordinator='22222222-2222-4222-8222-222222222222'
assignment=demo/'assignment';store=demo/'FIXTURE_STORE';protocol=OUT/'intake-protocol.json'
m.prepare(protocol,rendered,reviewer,store,assignment)
delivery=m.read(assignment/'DELIVERY_TEMPLATE.json');delivery.update(coordinator_registry_id=coordinator,delivered_utc=m.utcnow().isoformat().replace('+00:00','Z'),prior_exposure_confirmed_by_coordinator={'before_this_audit':'unknown','details':'TECHNICAL_FIXTURE: generated by script, no actual delivery to a person.'})
m.save(demo/'DELIVERY_FILLED_FIXTURE.json',delivery)
returned=m.read(assignment/'reviewer/cards.json');card=returned['cards'][0]
card.update(human_decision={'criteria':['uncertain']*3,'citation_sufficiency':['unreadable','not_selected','uncertain'],'contradiction':'uncertain','contradiction_fragment_ids':[]},human_reason=None,reviewer_registry_id=reviewer,reviewed_utc=m.utcnow().isoformat().replace('+00:00','Z'),prior_exposure_declared={'before_this_audit':'unknown','details':'TECHNICAL_FIXTURE: no real reviewer exists.','saw_verifier_readout':True})
m.save(demo/'RETURN_INCOMPLETE_FIXTURE.json',returned)
rejected=m.receive(protocol,assignment,demo/'RETURN_INCOMPLETE_FIXTURE.json',demo/'DELIVERY_FILLED_FIXTURE.json',store)
assert not rejected['validation_passed']
card['human_reason']='TECHNICAL_FIXTURE only: all human criteria are deliberately uncertain, no pedagogical claim; unreadable and unselected refer only to displayed links.'
m.save(demo/'RETURN_FILLED_FIXTURE.json',returned)
accepted=m.receive(protocol,assignment,demo/'RETURN_FILLED_FIXTURE.json',demo/'DELIVERY_FILLED_FIXTURE.json',store)
repeated=m.receive(protocol,assignment,demo/'RETURN_FILLED_FIXTURE.json',demo/'DELIVERY_FILLED_FIXTURE.json',store)
assert accepted['validation_passed'] and repeated['repeat_of_saved_attempt']
summary={'scope':'TECHNICAL_FIXTURE_ONLY_NOT_HUMAN_DATA','model_calls':0,'actual_human_deliveries':0,'actual_human_reviews':0,'incomplete_rejected':True,'complete_fixture_validated':True,'uncertain_followup_preserved':accepted['followup'],'identical_repeat_deduplicated':True,'registered_fixture_acceptances':len(list((store/'accepted').iterdir()))}
m.save(demo/'SUMMARY.json',summary)
print(json.dumps(summary,ensure_ascii=False))
